import{z as A,x as i,o as r,c,q as s,j as d,D as E,d as o,s as l,S as n,b as a}from"./chunks/framework.C8m1ZpeB.js";const I=JSON.parse('{"title":"阻塞与非阻塞套接字","description":"","frontmatter":{"title":"阻塞与非阻塞套接字","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/socket-nonblock.md","filePath":"cs/socket-nonblock.md","lastUpdated":1791413859000}'),B={name:"cs/socket-nonblock.md"};function p(m,e,h,D,f,C){const t=i("Mermaid");return r(),c("div",null,[e[2]||(e[2]=s('<h1 id="阻塞与非阻塞套接字" tabindex="-1">阻塞与非阻塞套接字 <a class="header-anchor" href="#阻塞与非阻塞套接字" aria-label="Permalink to &quot;阻塞与非阻塞套接字&quot;">​</a></h1><div class="epigraph"><p>默认 read 会把进程睡到有字节；非阻塞让调用立即返回「现在没有」，由事件通知再来读。</p><footer>—— 据 Stevens, UNIX Network Programming；Kurose and Ross 对套接字的整理</footer></div><p><a href="/cs/socket-api">上一课</a>把 UDP/TCP 接到文件描述符：<code>connect</code>、<code>accept</code>、<code>read</code>、<code>write</code>。本课不重列调用。缺口是等待：阻塞套接字上，对端慢则线程卡在系统调用里；并发连接若一人一线程，<a href="/cs/thread-shared-addr">进程/线程</a> 成本会先爆。非阻塞加多路复用是同一 API 上的调度合同。网络课在此结束，下一课转入物理层：香农容量在链路。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Berkeley 套接字默认阻塞：无数据则睡眠，缓冲满则写睡眠。这与<a href="/cs/file-bytestream">文件字节流</a>一致，但网络延迟是对端与路径，不是磁盘臂。服务器要同时服务许多已建立连接，不能为每个 <code>read</code> 配一个内核线程当默认。缺口是<strong>调用是否等待就绪</strong>，不是新的 TCP 状态。</p><p><span class="marginnote"><code>select</code>/<code>poll</code>/<code>epoll</code>/<code>kqueue</code> 都是「等这些描述符可读可写」。本课只钉合同，不选哪一个可移植层。</span></p><p><span class="marginnote">阻塞 read 可以类比成快餐店点单后一直站在柜台前干等，汉堡做好才挪步；非阻塞是点完单拿个叫号器就走——叫号器一响（事件通知）再回来取餐。等餐时间你可以干别的事，于是一个服务员（线程）就能同时照看几十个号。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设非阻塞：<code>read</code> 无数据返回 EAGAIN；<code>connect</code> 可在进行中返回。事件循环：注册描述符，醒来后在就绪集合上读写，直到再次 EAGAIN。阻塞套接字仍适合简单客户端。半关闭与 <a href="/cs/tcp-time-wait">TIME_WAIT</a> 不因非阻塞消失。</p>',9)),(r(),d(n,null,{default:E(()=>[l(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20BLK%5B%22%E9%98%BB%E5%A1%9E%20read%22%5D%20--%3E%20SLEEP%5B%22%E6%97%A0%E6%95%B0%E6%8D%AE%E5%88%99%E7%9D%A1%E7%9C%A0%22%5D%0A%20%20NB%5B%22%E9%9D%9E%E9%98%BB%E5%A1%9E%20read%22%5D%20--%3E%20AGAIN%5B%22%E7%AB%8B%E5%8D%B3%20EAGAIN%22%5D%0A%20%20AGAIN%20--%3E%20MUX%5B%22%E4%BA%8B%E4%BB%B6%E5%A4%9A%E8%B7%AF%E5%86%8D%E8%AF%BB%22%5D%0A"})]),fallback:E(()=>[...e[0]||(e[0]=[o(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("p",null,[a("span",{class:"marginnote"},"EAGAIN 的字面意思是「资源暂不可用，请待会儿再试」。它不是错误，而是非阻塞世界里的一句「现在没有」——初学者容易把它当异常去重试或报错，实际上事件循环遇到它就安静跳过，等下次就绪通知再来。")],-1)),e[4]||(e[4]=a("h2",{id:"机制",tabindex:"-1"},[o("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[5]||(e[5]=a("p",null,[o("非阻塞把等待从「藏在系统调用里」变成「进程自己调度」，与内核"),a("a",{href:"/cs/timeslice-cfs"},"时间片"),o(" 分工：内核仍唤醒，用户决定先服务谁。它不改 TCP 窗口与拥塞；只改线程是否被占住。数据库在后课另起：套接字送来的是字节，还没有表。")],-1)),(r(),d(n,null,{default:E(()=>[l(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20REG%5B%22%E6%B3%A8%E5%86%8C%E5%85%B3%E5%BF%83%E7%9A%84%E6%8F%8F%E8%BF%B0%E7%AC%A6%E9%9B%86%E5%90%88%22%5D%20--%3E%20WAIT%5B%22epoll_wait%EF%BC%9A%3Cbr%2F%3E%E6%97%A0%E7%BA%BF%E7%A8%8B%E7%A9%BA%E8%BD%AC%E5%9C%B0%E7%9D%A1%22%5D%0A%20%20WAIT%20--%3E%7C%22%E5%86%85%E6%A0%B8%E5%94%A4%E9%86%92%22%7C%20RDY%5B%22%E6%8B%BF%E5%88%B0%E5%B0%B1%E7%BB%AA%E9%9B%86%E5%90%88%22%5D%0A%20%20RDY%20--%3E%20DISP%5B%22%E9%80%90%E4%B8%AA%E5%88%86%E5%8F%91%E5%A4%84%E7%90%86%E5%99%A8%22%5D%0A%20%20DISP%20--%3E%20IO%5B%22read%20%2F%20write%20%E7%9B%B4%E5%88%B0%20EAGAIN%22%5D%0A%20%20IO%20--%3E%7C%22%E6%9C%AC%E8%BD%AE%E5%A4%84%E7%90%86%E5%AE%8C%22%7C%20WAIT%0A%20%20IO%20--%3E%7C%22%E8%BF%9E%E6%8E%A5%E4%BB%8D%E6%9C%89%E6%9C%AA%E8%AF%BB%E5%AE%8C%E6%95%B0%E6%8D%AE%22%7C%20REG%0A"})]),fallback:E(()=>[...e[1]||(e[1]=[o(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=s('<p><span class="marginnote">为什么不能一人一线程：每条线程默认占 1-8 MB 栈，一万条连接就是 10-80 GB 内存——只为「等着读数据」这一个动作。换成非阻塞加一个事件循环，同样一万条连接只要一个线程加一张就绪表，内存从 GB 级降到 MB 级。这就是本课说的「线程成本先爆」的具体含义。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把异步 I/O 的全部 POSIX 接口写完，不引入用户态协议栈。字节如何变成元组集合，是后课数据库的起点。</p><p>后课默认：网络端点可以不阻塞线程。持久共享数据需要关系，而不是再开一种套接字。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>阻塞等待就绪；非阻塞立即返回，靠多路复用再来。</li><li>不改变 TCP 语义，只改变进程调度。</li><li>网络课到此收束；下一课转入物理层的香农容量。</li><li>出处：Stevens <em>UNIX Network Programming</em>；Kurose and Ross。</li></ul>',6))])}const _=A(B,[["render",p]]);export{I as __pageData,_ as default};
